using System;namespace Recovered.Gameplay {public static class PtlPlatformLocks {public static void Enter(SoundSetupImage m,uint token,Func<SoundSetupImage,uint,uint[],uint> import){if(unchecked(token-1)>11)return;import(m,0x7510b8,new uint[]{unchecked(0x91ef70+token*24)});}public static void Exit(SoundSetupImage m,uint token,Func<SoundSetupImage,uint,uint[],uint> import){if(unchecked(token-1)>11)return;import(m,0x7510b4,new uint[]{unchecked(0x91ef70+token*24)});}public static uint Invoke(SoundSetupImage m,uint address,uint[] args,Func<SoundSetupImage,uint,uint[],uint> external){if(address==0x4ffaa0){Enter(m,args[0],external);return 0;}if(address==0x4ffac0){Exit(m,args[0],external);return 0;}return external(m,address,args);}public static void Refresh(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external){PtlMaterialComplete.Refresh(m,material,delegate(SoundSetupImage image,uint address,uint[] args){return Invoke(image,address,args,external);});}}}
